# owner: platform
"""Absence notices for parents, from attendance marks."""

from typing import Iterable, List

from rosterkit.models import Mark, Student
from rosterkit.attendance import days_missed

def join_words(words: List[str]) -> str:
    """Join words with commas and a final 'and'."""
    if len(words) == 1:
        return words[0]
    return ", ".join(words[:-1]) + " and " + words[-1]

def absence_notice(
    student: Student, marks: Iterable[Mark]
) -> str:
    """Notice naming the student and each absent day."""
    own_marks = list(marks)
    for mark in own_marks:
        if mark.student_id != student.student_id:
            raise ValueError(
                f"mark is for {mark.student_id}, "
                f"not {student.student_id}"
            )
    missed = days_missed(own_marks)
    if not missed:
        raise ValueError(
            f"no absences for {student.student_id}"
        )
    dates = join_words(
        [item.isoformat() for item in missed]
    )
    noun = "day" if len(missed) == 1 else "days"
    name = f"{student.first_name} {student.last_name}"
    return (
        f"{name} was absent {len(missed)} {noun} "
        f"in this class: {dates}."
    )
